<script setup lang="ts">
import {ref} from 'vue';import {post,fmt} from '../api'
defineProps<{athletes:any[]}>();const emit=defineEmits(['refresh','select'])
const show=ref(false),error=ref(''),busy=ref(false),form=ref({first_name:'',last_name:'',age:30,ftp_w:null as number|null})
async function save(){busy.value=true;error.value='';try{const a=await post('/athletes',{...form.value,ftp_w:form.value.ftp_w||null});show.value=false;emit('refresh');emit('select',a)}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="page-heading"><div><p class="eyebrow">IL TUO STUDIO</p><h1>Atleti</h1><p>Dallo storico alla previsione, con ogni passaggio tracciato.</p></div><button @click="show=!show">+ Aggiungi atleta</button></div><form v-if="show" class="card form-grid" @submit.prevent="save"><label>Nome<input v-model="form.first_name" required></label><label>Cognome<input v-model="form.last_name" required></label><label>Età<input type="number" min="1" max="120" v-model.number="form.age" required></label><label>FTP · W <small>opzionale</small><input type="number" min="1" v-model.number="form.ftp_w" placeholder="Non disponibile"></label><div class="error" v-if="error">{{error}}</div><button :disabled="busy">Crea atleta</button></form><div class="empty" v-if="!athletes.length&&!show"><div class="empty-symbol">P → HR</div><h2>Il prossimo esperimento inizia qui.</h2><p>Aggiungi un atleta e importa il suo storico FIT.<br>La prima identificazione partirà soltanto quando la avvierai tu.</p><button @click="show=true">Aggiungi il primo atleta</button></div><div class="athlete-grid" v-else><button class="athlete-card" v-for="a in athletes" @click="emit('select',a)"><span class="avatar">{{a.first_name[0]}}{{a.last_name[0]}}</span><h2>{{a.first_name}} {{a.last_name}}</h2><p>{{a.age}} anni · FTP {{a.ftp_w?fmt(a.ftp_w)+' W':'non indicata'}}</p><span class="link">Apri lo studio →</span></button></div><div class="principles"><div><small>01 / DATI</small><h3>Originali preservati</h3><p>Importazioni successive, nessuna sovrascrittura dei FIT.</p></div><div><small>02 / MODELLI</small><h3>Versioni esplicite</h3><p>Power response + P1D HR. Nessun aggiornamento automatico.</p></div><div><small>03 / VERIFICA</small><h3>Prima prevedi, poi confronti</h3><p>La previsione salvata resta distinta dalla diagnostica successiva.</p></div></div></template>
